lessons.solution:
#include <stdio.h>

/* Lesson 5 of 6 — Array.
   TODO: add nums[i] into sum */

int main(void) {
    int nums[4];
    int i;
    int sum;
    nums[0] = 2;
    nums[1] = 4;
    nums[2] = 6;
    nums[3] = 8;
    sum = 0;
    for (i = 0; i < 4; i = i + 1) {
        sum = sum + nums[i];
    }
    printf("%d\n", sum);
    return 0;
}

